-- Rollback-only integration tests: no emails, real orders, or money movement.
create temp table managed_results(checks jsonb);
do $$
declare a uuid;s uuid:=gen_random_uuid();b uuid:=gen_random_uuid();other uuid:=gen_random_uuid();d uuid:=gen_random_uuid();d2 uuid:=gen_random_uuid();o uuid;cid uuid:=gen_random_uuid();receipt uuid:=gen_random_uuid();case_id uuid;p jsonb;terms jsonb;intake jsonb;items jsonb;address jsonb;r jsonb;checks jsonb:='[]';passed jsonb:='{"display":true,"keyboard":true,"battery":true,"storage":true,"ports":true,"performance":true,"bios":true,"ownership":true,"serial_match":true}';
begin
 select user_id into a from public.user_roles where role='admin' limit 1;
 begin
 insert into auth.users(id,email,email_confirmed_at,aud,role,raw_user_meta_data) values(s,'managed-seller-'||s||'@example.invalid',now(),'authenticated','authenticated',jsonb_build_object('seller_application',true,'full_name','QA Seller','shop_name','QA Managed Shop','phone','9000000000','city','Bangalore','business_address','QA private address Bangalore 560001')),(b,'managed-buyer-'||b||'@example.invalid',now(),'authenticated','authenticated','{}'),(other,'managed-other-'||other||'@example.invalid',now(),'authenticated','authenticated','{}');
 perform set_config('request.jwt.claim.sub',a::text,true);
 update public.marketplace_sellers set status='active' where id=s;
 terms:=public.marketplace_managed_policy();
 terms:=public.admin_marketplace_save_policy(terms||'{"service_pincodes":["560001"],"hub_address":"QA Laptap Hub, Bangalore 560001","hub_instructions":"Wait for ready notification"}');
 if (public.marketplace_commission_quote(9999,terms)->>'rate')::integer<>1200 or(public.marketplace_commission_quote(10000,terms)->>'rate')::integer<>1000 or(public.marketplace_commission_quote(20000,terms)->>'rate')::integer<>900 or(public.marketplace_commission_quote(40000,terms)->>'rate')::integer<>800 or(public.marketplace_commission_quote(70000,terms)->>'rate')::integer<>700 or(public.marketplace_commission_quote(1000,terms)->>'commission')::numeric<>799 then raise exception 'FAILED tier boundaries';end if;
 select to_jsonb(l)||jsonb_build_object('title','QA Managed Laptop','price',30000,'verified_at',null) into p from public.marketplace_listings l where id='9af8d415-26e1-4b7d-9f2c-0d7a7e988001';
 intake:='{"serial_number":"QA-SERIAL-001","ownership_confirmed":true,"accepted_terms":true,"collection_address":"QA private seller collection 560001","diagnostic_notes":"QA SSD battery keyboard diagnostics checked","evidence_paths":[]}';
 execute 'set local role authenticated';perform set_config('request.jwt.claim.sub',s::text,true);
 begin perform public.marketplace_save_device(d,p,intake||'{"accepted_terms":false}',true,(terms->>'version')::integer);raise exception 'FAILED missing consent';exception when others then if SQLERRM not like '%accept the commission%' then raise;end if;end;
 begin perform public.marketplace_save_device(gen_random_uuid(),p||'{"category":"desktop"}',intake,true,(terms->>'version')::integer);raise exception 'FAILED desktop submission';exception when others then if SQLERRM not like '%laptop listings only%' then raise;end if;end;
 perform public.marketplace_save_device(d,p,intake,true,(terms->>'version')::integer);
 if not exists(select 1 from public.marketplace_listings where id=d and status='draft' and review_status='pending') then raise exception 'FAILED review pending';end if;
 begin update public.marketplace_listings set status='published' where id=d;raise exception 'FAILED self publish';exception when others then if SQLERRM not like '%Laptap review%' then raise;end if;end;
 begin update public.marketplace_listings set review_status='approved' where id=d;raise exception 'FAILED self approve';exception when others then if SQLERRM not like '%Only Laptap%' then raise;end if;end;
 begin perform public.admin_marketplace_review_listing(d,'approved','Seller attempted approval',true);raise exception 'FAILED admin permission';exception when others then if SQLERRM not like '%Admin access%' then raise;end if;end;
 checks:=checks||jsonb_build_object('test','Commission boundaries, minimum fee, consent, submission privacy and self-publication guards','passed',true);
 perform set_config('request.jwt.claim.sub',other::text,true);
 if exists(select 1 from public.marketplace_listing_intake where listing_id=d) or exists(select 1 from public.marketplace_listings where id=d) then raise exception 'FAILED private intake/listing';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.admin_marketplace_review_listing(d,'approved','Diagnostics and ownership remotely reviewed',true);
 if not exists(select 1 from public.marketplace_listings where id=d and status='published' and review_status='approved' and verified_at is null and (commission_terms->>'commission')::numeric=2700 and (commission_terms->>'seller_net')::numeric=27300) then raise exception 'FAILED listing approval or commission';end if;
 -- Material changes hide an approved listing and require review again.
 perform set_config('request.jwt.claim.sub',s::text,true);
 perform public.marketplace_save_device(d2,p,intake,true,(terms->>'version')::integer);
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.admin_marketplace_review_listing(d2,'approved','QA second device remotely reviewed',true);
 perform set_config('request.jwt.claim.sub',s::text,true);
 update public.marketplace_listings set title='QA revised device details' where id=d2;
 if not exists(select 1 from public.marketplace_listings where id=d2 and status='draft' and review_status='pending' and commission_terms='{}') then raise exception 'FAILED edit review reset';end if;
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.admin_marketplace_review_listing(d2,'rejected','QA please clarify the changed specifications',true);
 perform set_config('request.jwt.claim.sub',s::text,true);
 if not exists(select 1 from public.marketplace_listing_intake where listing_id=d2 and review_note like '%clarify%') then raise exception 'FAILED review feedback';end if;
 perform public.marketplace_save_device(d2,p,intake,true,(terms->>'version')::integer);
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.admin_marketplace_review_listing(d2,'approved','QA corrected specifications reviewed',true);
 -- A later policy update cannot change the already accepted commission.
 perform public.admin_marketplace_save_policy(terms||'{"rate_under_40000":1100}');
 items:=jsonb_build_array(jsonb_build_object('listing_id',d,'fulfillment_method','delivery'));address:='{"name":"QA Buyer","phone":"9000000001","line1":"QA house test road","city":"Bangalore","state":"Karnataka","pincode":"560001"}';
 perform set_config('request.jwt.claim.sub',b::text,true);
 begin perform public.marketplace_place_order(cid,items,address,30000,true);raise exception 'FAILED fee tampering';exception when others then if SQLERRM not like '%price or delivery fee changed%' then raise;end if;end;
 r:=public.marketplace_place_order(cid,items,address,30299,true);o:=(r->'order_ids'->>0)::uuid;
 if r<>public.marketplace_place_order(cid,items,address,30299,true) then raise exception 'FAILED checkout idempotency';end if;
 r:=public.marketplace_buyer_orders();if (r->0->>'amount')::numeric<>30299 or(r->0->>'buyer_service_fee')::numeric<>299 or r->0?'admin_notes' or r->0->'operations'?'assigned_to' then raise exception 'FAILED buyer projection';end if;
 perform set_config('request.jwt.claim.sub',s::text,true);
 begin perform public.marketplace_seller_order_action(o,'confirmed','','','');raise exception 'FAILED seller fulfilment';exception when others then if SQLERRM not like '%Laptap manages%' then raise;end if;end;
 begin update public.marketplace_listings set title='Illegal ordered edit' where id=d;raise exception 'FAILED active edit';exception when others then if SQLERRM not like '%managed order%' then raise;end if;end;
 checks:=checks||jsonb_build_object('test','Admin review publishes, private data stays private, checkout includes buyer fee and preserves agreed commission; sellers cannot fulfil or edit reserved devices','passed',true);
 perform public.marketplace_save_payout_profile('{"recipient_name":"QA Seller","method":"upi","upi_id":"qaseller@bank"}');
 perform set_config('request.jwt.claim.sub',a::text,true);
 if not exists(select 1 from public.marketplace_orders where id=o and commission_amount=2700 and seller_net=27300 and acceptance_hours=48) then raise exception 'FAILED locked seller terms';end if;
 begin update public.marketplace_orders set payment_status='paid',payment_reference='fake' where id=o;raise exception 'FAILED fake paid';exception when others then if SQLERRM not like '%actual COD%' then raise;end if;end;
 begin update public.marketplace_orders set status='shipped',courier='QA',tracking_number='QA-123' where id=o;raise exception 'FAILED bypass fulfilment';exception when others then if SQLERRM not like '%Invalid order status transition%' and SQLERRM not like '%inspection%' then raise;end if;end;
 perform public.admin_marketplace_operation(o,'confirm','{"note":"Confirmed device availability with seller"}');
 perform public.admin_marketplace_operation(o,'schedule_inspection',jsonb_build_object('assigned_to','QA Inspector','inspection_at',now()+interval '1 hour'));
 begin perform public.admin_marketplace_operation(o,'inspection_passed','{"checks":{},"report":"QA report missing required checks"}');raise exception 'FAILED missing checklist';exception when others then if SQLERRM not like '%Every inspection check%' then raise;end if;end;
 perform public.admin_marketplace_operation(o,'inspection_passed',jsonb_build_object('checks',passed,'report','QA physical inspection passed all diagnostic checks. Serial and ownership match.'));
 perform public.admin_marketplace_operation(o,'schedule_pickup',jsonb_build_object('collection_at',now()+interval '2 hours'));
 perform public.admin_marketplace_operation(o,'collect','{"reference":"QA-COLLECTION-PROOF"}');
 begin perform public.admin_marketplace_operation(o,'pack','{"reference":"QA-PACK","wipe_confirmed":false,"packed":true}');raise exception 'FAILED wipe';exception when others then if SQLERRM not like '%actual data wipe%' then raise;end if;end;
 perform public.admin_marketplace_operation(o,'pack','{"reference":"QA-PACK","wipe_confirmed":true,"packed":true}');
 perform public.admin_marketplace_operation(o,'dispatch','{"courier":"QA Laptap","tracking":"QA-RUN-123"}');
 perform public.admin_marketplace_operation(o,'deliver','{"reference":"QA-DELIVERY-PROOF"}');
 begin perform public.admin_marketplace_payout_action(o,'start','','',false);raise exception 'FAILED premature payout';exception when others then if SQLERRM not like '%acceptance period%' then raise;end if;end;
 perform public.admin_marketplace_money_event(o,'collection',30299,'cash','QA-COD-'||o,'QA receipt verified',receipt,true);
 perform public.admin_marketplace_money_event(o,'collection',30299,'cash','QA-COD-'||o,'QA receipt verified',receipt,true);
 begin perform public.admin_marketplace_money_event(o,'collection',1,'cash','QA-EXTRA-'||o,'QA overcollect',gen_random_uuid(),true);raise exception 'FAILED overcollect';exception when others then if SQLERRM not like '%over-collection%' then raise;end if;end;
 perform public.admin_marketplace_record_cost(o,'inspection',300,'QA-COST-'||o,'QA actual inspection',gen_random_uuid());
 if (public.admin_marketplace_order_finance(o)->>'collected')::numeric<>30299 or(public.admin_marketplace_order_finance(o)->>'cost_total')::numeric<>300 then raise exception 'FAILED authoritative finance totals';end if;
 checks:=checks||jsonb_build_object('test','Inspection checklist, ownership, serial, pickup, wipe, packing and proof gate delivery; COD receipts are idempotent and cannot exceed total','passed',true);
 perform public.admin_marketplace_verify_payout_profile(s,true,'QA-BENEFICIARY','QA destination independently verified');
 execute 'reset role';update public.marketplace_settlements set unlock_at=now()-interval '1 second' where order_id=o;execute 'set local role authenticated';
 -- A buyer issue during the acceptance window prevents payout even after the clock elapses.
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.marketplace_report_order_issue(o,'QA request for clarification on battery report');
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.admin_marketplace_payout_action(o,'start','','',false);raise exception 'FAILED open issue payout';exception when others then if SQLERRM not like '%support case%' then raise;end if;end;
 select id into case_id from public.marketplace_returns where order_id=o and status='open' limit 1;
 perform public.admin_marketplace_resolve_managed_case(case_id,'resolved','QA report clarified and accepted by buyer',true);
 if cardinality(public.marketplace_payout_blockers(o))<>0 then raise exception 'FAILED eligible payout';end if;
 perform public.admin_marketplace_payout_action(o,'start','','',false);
 perform set_config('request.jwt.claim.sub',s::text,true);
 begin perform public.marketplace_save_payout_profile('{"recipient_name":"QA Seller","method":"upi","upi_id":"changed@bank"}');raise exception 'FAILED destination race';exception when others then if SQLERRM not like '%payout is in progress%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',a::text,true);
 begin perform public.admin_marketplace_payout_action(o,'paid','QA-TRANSFER-'||o,'',false);raise exception 'FAILED unconfirmed transfer';exception when others then if SQLERRM not like '%actual external transfer%' then raise;end if;end;
 perform public.admin_marketplace_payout_action(o,'paid','QA-TRANSFER-'||o,'',true);
 perform public.admin_marketplace_payout_action(o,'paid','QA-TRANSFER-'||o,'',true);
 perform set_config('request.jwt.claim.sub',b::text,true);
 perform public.marketplace_report_order_issue(o,'QA display discrepancy reported after delivery');
 perform set_config('request.jwt.claim.sub',a::text,true);
 perform public.admin_marketplace_money_event(o,'refund',30299,'cash','QA-REFUND-'||o,'Actual refund completed',gen_random_uuid(),true);
 if not exists(select 1 from public.marketplace_settlements where order_id=o and status='recovery_due' and reference='QA-TRANSFER-'||o) then raise exception 'FAILED payout recovery';end if;
 perform public.admin_marketplace_payout_action(o,'recovered','QA-RECOVERY-'||o,'',true);
 checks:=checks||jsonb_build_object('test','Payout requires payment, elapsed acceptance period and verified frozen destination; external proof required; refunds preserve transfer history and require seller recovery','passed',true);
 update public.marketplace_orders set admin_notes='QA reconciliation note after completed recovery' where id=o;
 if not exists(select 1 from public.marketplace_settlements where order_id=o and status='recovered') then raise exception 'FAILED recovery history lost';end if;
 begin update public.marketplace_orders set payment_status='paid' where id=o;raise exception 'FAILED refunded paid reset';exception when others then if SQLERRM not like '%unrefunded COD%' then raise;end if;end;
 -- Hub orders can be cancelled before collection; their payout is voided.
 begin
 insert into public.marketplace_orders(listing_id,seller_id,buyer_name,email,phone,address,amount,status,payment_status,payment_reference,payment_method,fulfillment_method) values(d2,s,'QA Buyer','qa@example.invalid','9000000001','QA hub address',30000,'pending','paid','QA-FAKE-INITIAL','pay_at_pickup','pickup');
 raise exception 'FAILED admin initially paid';exception when others then if SQLERRM not like '%Managed orders start unpaid%' then raise;end if;end;
 perform set_config('request.jwt.claim.sub',b::text,true);
 r:=public.marketplace_place_order(gen_random_uuid(),jsonb_build_array(jsonb_build_object('listing_id',d2,'fulfillment_method','pickup')),address,30299,true);
 o:=(r->'order_ids'->>0)::uuid;
 perform public.marketplace_cancel_buyer_order(o,'QA no longer need this hub device');
 perform set_config('request.jwt.claim.sub',a::text,true);
 if not exists(select 1 from public.marketplace_settlements where order_id=o and status='void') then raise exception 'FAILED cancellation settlement';end if;
 checks:=checks||jsonb_build_object('test','Edited listings return to review, rejection feedback reaches seller, unresolved buyer issues block payouts, cancelled hub orders void settlement','passed',true);
 raise exception using errcode='PZ007',message='Rollback managed fixtures';
 exception when sqlstate 'PZ007' then null;end;
 insert into pg_temp.managed_results values(checks);
end $$;
select checks as passed_checks from pg_temp.managed_results;
